}
```

after:
```jsx
function App() {
  const [count, setCount] = React.useState(1);
  const [report, setReport] = React.useState("Not recorded");
  function record() {
    setCount(count + 1);
    setReport("Read " + count);
  }
  return (
    <main>
      <p>Count: {count}</p>
      <output>{report}</output>
      <button onClick={record}>Record</button>
    </main>
  );
}
```
After one click, the screen shows `Count: 2` and `Read 1`. The report uses the count that this handler read before the update.
